import{_ as t,o,c as d,a2 as s}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"UXS-000 — Orrery UX architecture","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-000-orrery-ux-architecture.md","filePath":"uxs/UXS-000-orrery-ux-architecture.md"}'),r={name:"uxs/UXS-000-orrery-ux-architecture.md"};function a(n,e,c,i,h,l){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="uxs-000-—-orrery-ux-architecture" tabindex="-1">UXS-000 — Orrery UX architecture <a class="header-anchor" href="#uxs-000-—-orrery-ux-architecture" aria-label="Permalink to &quot;UXS-000 — Orrery UX architecture&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 (2026-11-11) Visual fidelity · n/a — this document holds no visual rules of its own IA anchor · <a href="./IA">IA.md</a> §overview Related · <a href="./decisions/README">UX decision records</a>, <a href="./CHANGE-INVENTORY">change inventory</a>, <a href="./records/README">UX records</a></p></blockquote><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>How Orrery&#39;s UX is designed, decided and kept true. It names the design artefacts, says which one is authoritative for what, fixes the path every UX change takes from the operator&#39;s feedback to shipped code and a guard test, and states what &quot;done&quot; means for one slice of work. The visual and interaction rules themselves live in the documents it points to.</p><p>The model is the Close Listening player&#39;s <code>UXS-000</code> (UX decisions, records, backfill ledger and change inventory), adapted: Orrery has no journeys document and no living mockup, and its decider is the operator.</p><h2 id="the-artefacts" tabindex="-1">The artefacts <a class="header-anchor" href="#the-artefacts" aria-label="Permalink to &quot;The artefacts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Artefact</th><th>Where</th><th>What it is</th><th>Ids</th></tr></thead><tbody><tr><td><strong>Surface specs</strong></td><td><a href="./">index</a>: <code>UXS-001</code> … <code>UXS-006</code>, <code>UXS-013</code> … <code>UXS-017</code></td><td>The visual and interaction contract for one surface or concern. Each anchors to a section of IA.md</td><td>UXS-NNN</td></tr><tr><td><strong>Information architecture</strong></td><td><a href="./IA"><code>IA.md</code></a></td><td>Surfaces, nav groups, shell regions, URL structure, shared tokens. Every UXS anchors to it by section</td><td><code>§section</code> anchors</td></tr><tr><td><strong>Design system doc</strong></td><td><code>docs/concept/05_Design_System.md</code></td><td>The long-form rules: colour, type, components, panel anatomy, scene conventions</td><td>headings</td></tr><tr><td><strong>Agent design rules</strong></td><td><code>AGENTS.md</code> §&quot;Design system — do not change without UXS update&quot;</td><td>The short version every coding agent reads before touching a style</td><td>—</td></tr><tr><td><strong>Architecture map</strong></td><td><code>docs/adr/TA.md</code></td><td>Every route, subsystem, scene, contract and constraint, each with the ADR that locked it. Carries the rendering rules that bind the look (for example the one-output-step rule)</td><td>sections</td></tr><tr><td><strong>Code and tokens</strong></td><td><code>src/lib/styles/tokens.css</code>, the components under <code>src/</code></td><td>What ships. <code>tokens.css</code> states in its first lines that it is authoritative for colour, type and spacing</td><td>CSS custom properties</td></tr><tr><td><strong>UX decisions</strong></td><td><a href="./decisions/README"><code>decisions/</code></a></td><td>One record per UX decision: context, options, the decision, its consequences. The operator decides. Specs and the rules documents state the rule and link the record. Architecture decisions stay ADRs</td><td>UXD-NNN</td></tr><tr><td><strong>Backfill ledger</strong></td><td><a href="./decisions/BACKFILL"><code>decisions/BACKFILL.md</code></a></td><td>Older UX decisions found in the specs, IA, AGENTS.md, ADRs and the operator&#39;s notes, one row each. History, not re-decided</td><td>B-NNN</td></tr><tr><td><strong>UX records</strong></td><td><a href="./records/README"><code>records/</code></a></td><td>Dated records of what happened: an operator feedback list, a review, a plan. Written once; a later event gets a new record</td><td>UXR-NNN</td></tr><tr><td><strong>Change inventory</strong></td><td><a href="./CHANGE-INVENTORY"><code>CHANGE-INVENTORY.md</code></a></td><td>Every UX slice in flight, the decisions behind it, its status, and which spec or ADR it will touch</td><td>slice ids (A1, B2 …)</td></tr><tr><td><strong>Working plans</strong></td><td><code>docs/wip/2026-11-11-ux-feedback-plan.md</code>, <code>…-0.9.9-plan.md</code>, <code>…-slice-*-brief.md</code></td><td>The operator&#39;s numbered feedback, the slice plan, the open questions, and one brief per slice. Not published (the docs build excludes <code>wip/</code>)</td><td>point ids (X1, P3 …), Q-ids, D-ids</td></tr><tr><td><strong>Guards</strong></td><td>see <a href="#guards">Guards</a></td><td>Tests and builds that keep a decided rule true</td><td>—</td></tr></tbody></table><p>The PRDs say what and why; ADRs and RFCs own architecture and behaviour; the UXS documents, IA and the design system own the visual and interaction contract.</p><h2 id="which-one-is-right" tabindex="-1">Which one is right <a class="header-anchor" href="#which-one-is-right" aria-label="Permalink to &quot;Which one is right&quot;">​</a></h2><ul><li><strong>The code is the truth about what ships.</strong> The specs and UXDs are the truth about what should ship. When they disagree it is a finding: log it as a spec-to-code mismatch (<a href="#spec-to-code-mismatches-open">below</a>), and decide it. Never resolve it silently in either direction.</li><li><strong>A UXD outranks the prose it changed.</strong> A rule in IA, a UXS, the design system doc or AGENTS.md that contradicts an accepted UXD is stale; fix the prose and link the UXD.</li><li><strong><code>tokens.css</code> outranks any restated number.</strong> A size, colour or spacing value in a document that differs from <code>tokens.css</code> is a mismatch to log, not a second source.</li><li><strong>The UXS boxes are not a record of what shipped.</strong> Each UXS carries an as-built note (2026-10-16, for example <code>UXS-001.md</code> line 93): for shipped behaviour read <code>docs/adr/TA.md</code> and <code>CHANGELOG.md</code>.</li><li><strong>Operator operator notes are inputs, not authority.</strong> A decision first recorded in a private note counts once it has a UXD or a backfill row that quotes its source and date.</li></ul><h2 id="how-a-ux-change-moves" tabindex="-1">How a UX change moves <a class="header-anchor" href="#how-a-ux-change-moves" aria-label="Permalink to &quot;How a UX change moves&quot;">​</a></h2><ol><li><strong>Operator feedback</strong> is captured as a dated record (<a href="./records/README">UXR</a>) with numbered points. The full list stays in the working plan; the record summarises it by area.</li><li><strong>Slice brief</strong> (read-only, before any code): the exact search patterns that define &quot;old&quot;, the full hit list across the repo, the allow-list with reasons, and the docs and tests that state or guard the rule. The implementer works from that list, not from sample screens.</li><li><strong>Decision</strong>: where a choice is open, the question goes to the operator once, before the slice that needs it. The answer is written as a <a href="./decisions/README">UXD</a>, <code>accepted</code> only on the operator&#39;s recorded go (date and where).</li><li><strong>Implement</strong> against the brief. Tests move with the work.</li><li><strong>Independent check</strong>: a fresh agent that did not write the code re-runs the brief&#39;s searches, the definition-of-done items and the affected suites on all three Playwright projects (<code>desktop-chromium</code>, <code>mobile-chromium</code>, <code>mobile-landscape-chromium</code>), and reviews the diff. Findings go back to the implementer; the slice loops until the checker reports clean.</li><li><strong>Operator screenshots</strong>: the lead reads the checker&#39;s evidence, then sends the operator small before/after screenshots (13-inch laptop and phone). The operator validates visually.</li><li><strong>State the rule</strong>: the specs, IA, the design system doc, AGENTS.md and TA.md say the new rule and link the UXD. A decision is not done until its rules say it.</li><li><strong>Guard</strong>: where the rule can be checked, a test is added, site-wide where possible.</li></ol><p>Method for the surface slices follows the <code>ux-baseline-review</code> flow: a before/after look first, the operator approving per screen, then the change, then e2e.</p><h2 id="definition-of-done-—-every-slice" tabindex="-1">Definition of done — every slice <a class="header-anchor" href="#definition-of-done-—-every-slice" aria-label="Permalink to &quot;Definition of done — every slice&quot;">​</a></h2><p>Operator, 2026-11-11 (&quot;no partial updates, quality over speed&quot;; plan lines 467–481 in <code>docs/wip/2026-11-11-ux-feedback-plan.md</code>). A slice is reported done only when the lead has checked all of these, with the command and its output:</p><ol><li><strong>Whole project.</strong> The decision is applied in every route and component, proven by a repo-wide search for the old pattern that returns nothing outside a documented allow-list.</li><li><strong>Docs.</strong> Every doc that states the rule says the new rule (AGENTS.md design rules, style guides, TA.md, READMEs of touched folders).</li><li><strong>Tests move with the work.</strong> Tests whose expectations changed are adjusted, new tests guard the rule (site-wide where possible), obsolete ones are removed; the affected suites are green on <code>desktop-chromium</code>, <code>mobile-chromium</code> and <code>mobile-landscape-chromium</code>, with nothing skipped or left red.</li><li><strong>Locales.</strong> Any new or changed text exists in all 14 locales through the glossary and the standard i18n tools; <code>validate-data</code> is green.</li><li><strong>The UXD exists and the rules link to it.</strong> Every decision the slice implements has an accepted <a href="./decisions/README">UXD</a>, and each spec, IA, design system, AGENTS.md or TA.md line that states the rule links to it. (Added to the operator&#39;s four by this document.)</li></ol><p>Then the operator gets a short status and small before/after screenshots (13-inch laptop and phone).</p><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guard</th><th>Keeps true</th></tr></thead><tbody><tr><td><code>tests/e2e/type-floor.spec.ts</code></td><td>no visible text below 11 px on any route in <code>scripts/site-routes.mjs</code> or in one open panel per panel type (see UXD-002)</td></tr><tr><td><code>src/lib/three/output-step-rule.test.ts</code></td><td>every <code>EffectComposer</code> ends in an OutputPass and colour textures carry a colour space (see UXD-004)</td></tr><tr><td><code>tests/e2e/scale-index.spec.ts</code></td><td>the INDEX on all eight scales: hidden but in the DOM, one Tab stop, search, 30 / 44 px targets, black holes by scale, scale jump (see UXD-017)</td></tr><tr><td><code>tests/e2e/select-focus.spec.ts</code></td><td>select = focus from every entry point, the ring rule, chip-off clears a selection (see UXD-019)</td></tr><tr><td><code>tests/e2e/explore-readability.spec.ts</code>, <code>src/lib/universe/scene-pins.test.ts</code></td><td>the 12 px label, the 44 px ring, the placement pass, the steady label offset (see UXD-020)</td></tr><tr><td><code>tests/e2e/visual.spec.ts</code> snapshots</td><td>the rendered baseline of the routes it covers; regenerated on the Linux runner when a decided rule changes them</td></tr><tr><td><code>npm run docs:build</code></td><td>every page under <code>docs/</code> builds with VitePress; no unresolved link</td></tr><tr><td><code>npm run preflight</code> (pre-push hook)</td><td>typecheck, lint, tests, <code>validate-data</code> and build. Does not run e2e and is not a byte-for-byte mirror of CI (see <code>CLAUDE.md</code>)</td></tr></tbody></table><p>A new shared rule that can be checked arrives with its check. Accepted rules with no guard yet: the link/accent colour (UXD-001, a repo-wide search for the old teal is the slice&#39;s check), the home route-card title (UXD-003), and three rules whose guard is planned in their slice: the panorama opening heading (UXD-007, e2e in slice D2), the deep-sky viewer fit (UXD-009), the ruler science cards (UXD-010, a unit test over the data in slice B2).</p><h2 id="open" tabindex="-1">Open <a class="header-anchor" href="#open" aria-label="Permalink to &quot;Open&quot;">​</a></h2><p>Nothing below is a UXD. Each moves to one when the operator answers.</p><p><strong>Operator decisions (asked once, before the phase that needs them)</strong> — plan lines 24–32 (D1 to D3 are answered: <a href="./decisions/UXD-039-home-two-column-hero-one-glyph-component-and-type-scale">UXD-039</a>; D4 is answered: keep the Explore dropdown, <a href="./decisions/UXD-027-explore-levels-one-table-glyphs-card-and-hint">UXD-027</a>; D5 is answered: an explicit link both ways, no switch on zoom, <a href="./decisions/UXD-028-explore-and-worlds-link-both-ways">UXD-028</a>; D6 is answered: on 2026-11-14 the operator shared nine example shots, the launch camera is slice G3, <a href="./../wip/2026-11-14-slice-G3-brief">G3 brief</a> §2.7, no UXD yet):</p><table tabindex="0"><thead><tr><th>Id</th><th>Question</th></tr></thead><tbody><tr><td>D7</td><td>Missions era filter designed with Higgsfield (paid) or in code</td></tr></tbody></table><p><strong>Questions for the operator</strong> — plan lines 402–414 (Q1 and Q2 are answered: UXD-001, UXD-002; Q7 and Q9 are answered: UXD-038; Q10 is answered: UXD-041; Q8 is answered 2026-11-13: line style only, UXD-044):</p><table tabindex="0"><thead><tr><th>Id</th><th>Question</th></tr></thead><tbody><tr><td>Q3</td><td>&quot;Share&quot;: a renamed card overlay, or a real share-link action?</td></tr><tr><td>Q4</td><td>A mission link in a body panel: open the mission panel in place, or go to <code>/missions</code>?</td></tr><tr><td>Q5</td><td>Chip groups: group every world (On ground / In space), or flatten Earth?</td></tr><tr><td>Q6</td><td>Panel close X: scrolls away with the content, or a slim fixed header bar?</td></tr></tbody></table><p><strong>Clarified from screenshots, fix described, no separate operator go recorded</strong> (plan lines 417–425): MW3 (Sagittarius A* panel gets the EHT 2022 image as its hero; the lensing render becomes an explicit action). It is planned in slice B3 and becomes a UXD with the slice&#39;s screenshots.</p><p><strong>To check at the end (operator, 2026-11-11)</strong> — plan lines 462–465: science diagrams and Lab art keep their own colours for now; review whether they should also move to the new palette once the UI blue is in place.</p><p><strong>Unreconciled between decisions</strong> (found while writing this document, not decided anywhere; the <code>#889fe7</code> question is settled: it stays beside blue D, UXD-001, plan line 460):</p><ul><li>The plan says &quot;lead/overview 15–16 px&quot; for Q2; the tokens say 16 px, 15 px under 600 px width (UXD-002 records the tokens).</li></ul><h3 id="spec-to-code-mismatches-open" tabindex="-1">Spec-to-code mismatches (open) <a class="header-anchor" href="#spec-to-code-mismatches-open" aria-label="Permalink to &quot;Spec-to-code mismatches (open)&quot;">​</a></h3><p>Read at commit <code>9fdf4cc4a6b</code>. Logged, not resolved here (another change set is editing those files).</p><table tabindex="0"><thead><tr><th>Id</th><th>Document says</th><th>Code says</th></tr></thead><tbody><tr><td>SC-1</td><td>CLOSED by slice A6 (2026-11-12): one 52 px bar from one token, <code>--nav-bar-height: 52px</code>, <code>--nav-height</code> built from it, and the docs name the real nav z-index 40 (IA said 20). Was: nav bar height 52 px in <code>IA.md</code> lines 52–55, 179, 236; <code>AGENTS.md</code> line 747; <code>05_Design_System.md</code> lines 158, 207 (<a href="./decisions/UXD-016-compact-nav-and-more-menu">UXD-016</a>)</td><td><code>--nav-bar-height: 52px</code> in <code>tokens.css</code> (was 60 px, and <code>--nav-height</code> re-typed <code>60px</code>)</td></tr><tr><td>SC-2</td><td>CLOSED (plan L34, 2026-11-15): <code>IA.md</code>, <code>AGENTS.md</code> and <code>05_Design_System.md</code> say 400 px (<code>--panel-width</code>). Was: desktop panel width 314 px: <code>IA.md</code> lines 181, 237; <code>AGENTS.md</code> lines 501, 749; <code>05_Design_System.md</code> line 167</td><td><code>--panel-width: 400px</code> in <code>tokens.css</code> (its own comment: 314 → 360 → 400)</td></tr><tr><td>SC-3</td><td><code>--color-text-dim</code> is <code>rgba(255,255,255,0.35)</code>: <code>IA.md</code> line 203; <code>05_Design_System.md</code> line 51 (0.25–0.35)</td><td><code>--color-text-dim: rgba(255, 255, 255, 0.6)</code> in <code>tokens.css</code></td></tr><tr><td>SC-4</td><td>CLOSED by slice A3 (2026-11-12): UI teal is gone, the tokens and docs say blue (UXD-001). Was: spec versus decision (not spec versus code): teal <code>#4ecdc4</code> is a design colour (<code>IA.md</code> line 198; <code>AGENTS.md</code> line 720; <code>05_Design_System.md</code> line 48; UXS-002/003 HUD and CAPCOM colours)</td><td>UXD-001 says every UI teal becomes blue, but <code>tokens.css</code> lines 14 and 33 (<code>--color-teal</code>, <code>--color-tier-intro</code>) still define <code>#4ecdc4</code> until slice A3</td></tr><tr><td>SC-5</td><td>CLOSED by slice A3 (2026-11-12): <code>--color-accent</code> is <code>#5070ff</code>, the one UI accent, <code>#4466ff</code> retired, <code>--color-accent-text</code> kept as an alias. Was: <code>IA.md</code> line 197 and <code>AGENTS.md</code> line 719 name the accent <code>#4466ff</code> (&quot;Primary accent&quot;, &quot;Accent blue&quot;)</td><td><code>tokens.css</code> line 9 <code>--color-accent: #4466ff</code> (brand: borders, outlines, fills) and line 13 <code>--color-accent-text: #5070ff</code> (the accent as text). UXD-001 calls <code>#5070ff</code> the &quot;link blue&quot; / UI accent. Which token is the UI accent, and whether <code>#4466ff</code> stays for borders and fills, is left for slice A3 to settle</td></tr></tbody></table><h2 id="next-—-lines-that-must-link-to-a-uxd" tabindex="-1">Next — lines that must link to a UXD <a class="header-anchor" href="#next-—-lines-that-must-link-to-a-uxd" aria-label="Permalink to &quot;Next — lines that must link to a UXD&quot;">​</a></h2><p>Owner: the change set that edits these files (not this one). Each line states the current rule and</p><p>History note: the line numbers and &quot;teal&quot; wording in this table describe the files as they were before slice A3 (2026-11-12); those lines now say blue. gains a link to the UXD, in the same change as the rule.</p><table tabindex="0"><thead><tr><th>File and lines</th><th>Must link to</th></tr></thead><tbody><tr><td><code>AGENTS.md</code> 717–723 (colour block: &quot;Teal&quot;, &quot;Accent blue&quot;)</td><td>UXD-001</td></tr><tr><td><code>AGENTS.md</code> 729–745 (type scale, floor, italic rule, canvas allow-list)</td><td>UXD-002</td></tr><tr><td><code>AGENTS.md</code> 747–750 (nav 52 px, panel 314 px) — fix to the tokens first (SC-1, SC-2)</td><td>none (mismatch); then UXS-000 §Spec-to-code mismatches</td></tr><tr><td><code>AGENTS.md</code> §&quot;Performance — 3D scene discipline&quot; (line 537 onward): add the one-OutputPass rule</td><td>UXD-004</td></tr><tr><td><code>AGENTS.md</code> 91 and 959 (no staging tier)</td><td>UXD-005 (and ADR-097)</td></tr><tr><td><code>docs/adr/TA.md</code> 371 (composer pipeline and colour, one output step)</td><td>UXD-004</td></tr><tr><td><code>docs/uxs/IA.md</code> 193–215 (colour tokens, link tier colours, teal at 198 and 213)</td><td>UXD-001</td></tr><tr><td><code>docs/uxs/IA.md</code> 218–231 (typography tokens)</td><td>UXD-002</td></tr><tr><td><code>docs/uxs/IA.md</code> 121–152 (§home-cards)</td><td>UXD-003 (route-card titles, the removed icon text)</td></tr><tr><td><code>docs/uxs/IA.md</code> 233–242 (spacing tokens 52 px, 314 px) and 203 (text-dim)</td><td>none (SC-1, SC-2, SC-3 first)</td></tr><tr><td><code>docs/uxs/UXS-013.md</code> 63 (<code>--size-lead</code>) and the hero/card typography section</td><td>UXD-002, UXD-003</td></tr><tr><td><code>docs/uxs/UXS-001.md</code> (detail panel tabs; no star-panel section today)</td><td>UXD-008, UXD-023 (star-panel section added in B3), UXD-002 (panel overview text)</td></tr><tr><td><code>docs/uxs/UXS-002.md</code> 38, 40, 65, 84 and <code>UXS-003.md</code> 42, 89–90 (teal HUD and CAPCOM)</td><td>UXD-001</td></tr><tr><td><code>docs/uxs/UXS-004.md</code>, <code>UXS-005.md</code>, <code>UXS-006.md</code> (size and italic lines)</td><td>UXD-002</td></tr><tr><td><code>docs/uxs/UXS-006.md</code> (Moon map; no panorama section today)</td><td>UXD-007 (add a panorama section; surface sites share the scene, ADR-072)</td></tr><tr><td><code>docs/uxs/UXS-014.md</code> 25 onward (&quot;Selecting &amp; understanding an object&quot;)</td><td>UXD-008, UXD-023 (star and outer panels), UXD-010 (orbit ruler science cards; no ruler section today)</td></tr><tr><td><code>docs/uxs/UXS-016.md</code> §1 (scale ladder rail)</td><td>UXD-010 only if the ruler is specified there; otherwise none</td></tr><tr><td><code>docs/concept/05_Design_System.md</code> 48, 58, 61, 72, 87, 90, 97, 432 (teal)</td><td>UXD-001</td></tr><tr><td><code>docs/concept/05_Design_System.md</code> 125, 144–148, 215 (type rules)</td><td>UXD-002</td></tr><tr><td><code>docs/concept/05_Design_System.md</code> 158, 167, 207, 360 (52 px, 314 px)</td><td>none (SC-1, SC-2)</td></tr><tr><td><code>docs/guides/</code> and <code>docs/ops/*</code> that name staging</td><td>UXD-005 (and ADR-097)</td></tr><tr><td><code>docs/adr/ADR-014.md</code>, <code>ADR-070.md</code>, <code>ADR-071.md</code>, <code>ADR-082.md</code>, <code>ADR-083.md</code></td><td>already carry their supersession by ADR-097 (not UX; listed for completeness)</td></tr><tr><td><code>docs/uxs/UXS-017.md</code> (the gallery family, added with F4)</td><td>UXD-009, UXD-040 (the viewer fit rule is §2)</td></tr></tbody></table><p>Line numbers are as read at <code>9fdf4cc4a6b</code>; re-grep before editing.</p><p><strong>UXD-030 to UXD-047 (plan L10, 2026-11-15).</strong> Each record is linked from the rules it changes: the IA §surfaces, §controls, §url-structure or §shared-tokens line (all eighteen), the TA.md section (all eighteen, the record in the same section as the contract), the Design System section (all but UXD-036 and UXD-041, which set no visual rule), and the UXS it amends: UXS-002 and UXS-003 (UXD-042, 043, 046, 047), UXS-004 (UXD-035), UXS-005 (UXD-030, 031, 034), UXS-006 (UXD-030, 034, 036, 044), UXS-013 (UXD-039), UXS-014 (UXD-037, 045), UXS-017 (UXD-040). UXD-032, 033, 038 and 041 amend no UXS (programs, the long text pages and the library are IA and TA rows, not a UXS); AGENTS.md carries UXD-038 (the 10-row rule) and UXD-045 (the INDEX row glyph) because those are rules an agent writes code against.</p><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to &quot;Revision history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-11-11</td><td>Created: the artefacts, precedence, the change flow, the definition of done, the guards and the open items</td></tr></tbody></table>',41)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
